202	/// Converts a TOON validation failure into a [`michi::DomainError`].
203	///
204	/// It bypasses [`ToDomainError`] because this is not a [`MonoklError`]: it means this module built an invalid row or
205	/// field, not that the caller supplied bad input.
206	pub fn toon_validation_error(e: &michi::toon::ToonError) -> michi::DomainError {
207	    michi::DomainError::new(michi::ErrorCode::ExternalFailure, format!("toon_render_invalid: {e}")).retryable(false)
208	}
